SELECT 
FROM sys_role
WHERE deleted = 0

    AND name LIKE CONCAT('%', #{name}, '%')


    AND code LIKE CONCAT('%', #{code}, '%')


    AND status = #{status}


    AND create_time >= #{beginTime}


    AND create_time <= #{endTime}

mapper.update:
UPDATE sys_role
name = #{name}, code = #{code}, sort = #{sort}, data_scope = #{dataScope}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = NOW(), version = version + 1
WHERE id = #{id} AND deleted = 0 AND version = #{version}

